nts SET class_level=?,subject=? WHERE id=? AND school_id=? AND active=1');$q->execute([$class,$subject,$id,$schoolId]);if(!$q->rowCount()){ $verify=$pdo->prepare('SELECT id FROM teacher_assignments WHERE id=? AND school_id=? AND active=1');$verify->execute([$id,$schoolId]);if(!$verify->fetch())throw new DomainException('That assignment is no longer available.');}$auditAction='update';}$entity='teacher_assignment';}elseif($action==='remove_assignment'&&$canAssign){$id=(int)($_POST['record_id']??0);$q=$pdo->prepare('DELETE FROM teacher_assignments WHERE id=? AND school_id=?');$q->execute([$id,$schoolId]);if(!$q->rowCount())throw new DomainException('That assignment is no longer available.');$entity='teacher_assignment';$auditAction='delete';}
