assOption['school_id']?>"><?php endforeach;?></datalist><label for="edit-assignment-subject-<?=$a['id']?>">Subject</label><input id="edit-assignment-subject-<?=$a['id']?>" name="subject" list="edit-assignment-subjects-<?=$a['id']?>" data-academic-subject-input value="<?=e($a['subject'])?>" required maxlength="100" autocomplete="off"><datalist id="edit-assignment-subjects-<?=$a['id']?>" data-academic-subject-options><?php foreach($academicSubjects as $subjectOption):?><option value="<?=e($subjectOption['subject_name'])?>" data-school-id="<?=$subjectOption['school_id']?>" data-class-name="<?=e($subjectOption['class_name'])?>"><?php endforeach;?></datalist><small class="muted" data-class-hint></small><small class="muted" data-subject-hint></small><button type="submit" class="button primary">Save changes</button></form></details><form method="post" class="academic-async academic-remove-assignment" onsubmit="return confirm('Remove this teacher assignment?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove_assignment"><input type="hidden" name="record_id" value="<?=$a['id']?>"><input type="hidden" name="school_id" value="<?=$a['school_id']?>"><button type="submit" class="button danger">Remove</button></form></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="note-create academic-launch-panel"><div class="section-heading"><div><div class="eyebrow">PUPILS</div><h2>Pupils directory</h2></div><button type="button" class="button primary" data-open-academic-dialog="pupils-directory-dialog">Open directory</button></div><p class="muted">Search pupil records, admission numbers, classes and scholar types.</p></section><dialog class="academic-dialog academic-dialog-wide" id="pupils-directory-dialog" data-academic-dialog aria-labelledby="pupils-directory-title"><div class="academic-dialog-head"><div><div class="eyebrow">SCHOOL RECORDS</div><h2 id="pupils-directory-title">Pupils directory</h2><p class="muted">Search and review pupils registered in your school access.</p></div><button type="button" class="icon-button" data-close-academic-dialog aria-label="Close pupils directory">×</button></div><div class="academic-dialog-content"><section class="academic-list-section academic-directory-content" data-academic-list><div class="section-heading"><div><div class="eyebrow">PUPIL DIRECTORY</div><h2>Pupils</h2></div><span class="count-pill"><?=count($pupils)?> pupils</span></div><?php if($pupils):?><div class="academic-table-tools"><label class="sr-only" for="filter-pupils">Search pupils</label><input id="filter-pupils" type="search" data-academic-filter placeholder="Search name, admission or class" autocomplete="off"><span data-filter-status aria-live="polite"></span></div><div class="table-wrap"><table><thead><tr><th>Admission</th><th>Pupil</th><th>School / class</th><th>Scholar type</th></tr></thead><tbody><?php foreach($pupils as $p):?><tr><td><?=e($p['admission_number'])?></td><td><?=e($p['first_name'].' '.$p['last_name'])?></td><td><?=e($p['school_name'].' · '.$p['class_level'].($p['stream']?' / '.$p['stream']:''))?></td><td><?=e(ucfirst($p['scholar_type']))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No pupils registered</h3><p>Register a pupil to begin building the school directory.</p></div><?php endif;?></section></div><div class="academic-dialog-actions"><button type="button" class="button" data-close-academic-dialog>Done</button></div></dialog><section class="content-section academic-list-section" data-academic-list><div class="section-heading"><div><div class="eyebrow">ASSESSMENT RECORDS</div><h2>Exam results</h2></div></div><?php if($results):?><div class="academic-table-tools"><label class="sr-only" for="filter-results">Search results</label><input id="filter-results" type="search" data-academic-filter placeholder="Search exam, pupil, subject or paper" autocomplete="off"><span data-filter-status aria-live="polite"></span></div><div class="table-wrap"><table><thead><tr><th>Exam</th><th>Pupil</th><th>Class</th><th>Subject</th><th>Assessment / paper</th><th>Score</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?=e($r['exam_name'])?> · <?=e((string)$r['academic_year'])?></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['class_level'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['assessment'])?></td><td><?=e($r['score'].' / '.$r['max_score'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No results yet</h3><p>Saved assessment results will appear here.</p></div><?php endif;?></section><?php if($canRegister):?><dialog class="academic-dialog" id="register-pupil-dialog" data-academic-dialog aria-labelledby="register-pupil-title"><form method="post" class="note-form academic-async"><div class="academic-dialog-head"><div><div class="eyebrow">PUPIL RECORD</div><h2 id="register-pupil-title">Register a pupil</h2><p class="muted">Enter the pupil’s details to add them to the directory.</p></div><button type="button" class="icon-button" data-close-academic-dialog aria-label="Close registration form">×</button></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="pupil"><div class="form-grid"><?=render_school_select('school',$schools)?><div><label for="admission">Admission number</label><input name="admission_number" id="admission" required maxlength="60"></div><div><label for="first">First name</label><input name="first_name" id="first" required maxlength="80"></div><div><label for="last">Last name</label><input name="last_name" id="last" required maxlength="80"></div><div><label for="class">Class level</label><input name="class_level" id="class" required maxlength="80" placeholder="Grade 4"></div><div><label for="stream">Stream</label><input name="stream" id="stream" maxlength="80"></div><div><label for="dob">Date of birth</label><input name="date_of_birth" id="dob" type="date"></div><div><label for="scholar">Day or boarding</label><select name="scholar_type" id="scholar"><option value="day">Day scholar</option><option value="boarding">Boarding scholar</option></select></div><div><label for="guardian">Guardian name</label><input name="guardian_name" id="guardian" maxlength="140"></div><div><label for="phone">Guardian phone</label><input name="guardian_phone" id="phone" type="tel" maxlength="30"></div></div><div class="academic-dialog-actions"><button type="button" class="button" data-close-academic-dialog>Cancel</button><button class="button primary" type="submit">Register pupil</button></div></form></dialog><?php endif;?>
<?php endif;?></div></main></div><script>
(()=>{
const page=()=>document.querySelector('.academic-page');
const setupClassAutocomplete=(scope=document)=>{scope.querySelectorAll('form.academic-assignment-form').forEach(form=>{const school=form.querySelector('[name=school_id]'),classInput=form.querySelector('[data-academic-class-input]'),classList=form.querySelector('[data-academic-class-options]'),subjectInput=form.querySelector('[data-academic-subject-input]'),subjectList=form.querySelector('[data-academic-subject-options]'),button=form.querySelector('[type=submit]'),classHint=form.querySelector('[data-class-hint]'),subjectHint=form.querySelector('[data-subject-hint]');if(!school||!classInput||!classList||!subjectInput||!subjectList)return;const allClasses=[...classList.options].map(option=>({name:option.value,school:option.dataset.schoolId}));const allSubjects=[...subjectList.options].map(option=>({name:option.value,school:option.dataset.schoolId,className:option.dataset.className}));const refreshSubjects=clear=>{const exactClass=allClasses.some(item=>item.school===school.value&&item.name.toLocaleLowerCase()===classInput.value.trim().toLocaleLowerCase());const matches=exactClass?allSubjects.filter(item=>item.school===school.value&&item.className.toLocaleLowerCase()===classInput.value.trim().toLocaleLowerCase()):[];subjectList.replaceChildren(...matches.map(item=>{const option=document.createElement('option');option.value=item.name;return option}));if(clear)subjectInput.value='';subjectInput.disabled=matches.length===0;if(subjectHint)subjectHint.textContent=matches.length?'Type to search subjects saved for this class.':'Choose a saved class to see its subjects.';if(button)button.disabled=classInput.disabled||subjectInput.disabled};const refreshClasses=clear=>{const matches=allClasses.filter(item=>school.value&&item.school===school.value);classList.replaceChildren(...matches.map(item=>{const option=document.createElement('option');option.value=item.name;return option}));if(clear)classInput.value='';classInput.disabled=matches.length===0;if(classHint)classHint.textContent=matches.length?'Type to search classes saved for this school.':'No classes have been saved for the selected school.';refreshSubjects(clear);if(button)button.disabled=matches.length===0||subjectInput.disabled};school.addEventListener('change',()=>refreshClasses(true));classInput.addEventListener('input',()=>refreshSubjects(false));classInput.addEventListener('change',()=>refreshSubjects(true));subjectInput.addEventListener('input',()=>{if(button)button.disabled=classInput.disabled||subjectInput.disabled});refreshClasses(false)})};
setupClassAutocomplete();
const announce=(message,kind='success')=>{let box=document.querySelector('.academic-feedback')||document.querySelector('.academic-page>.notice');if(!box){box=document.createElement('div');box.className='notice academic-feedback';box.setAttribute('role','status');page()?.prepend(box)}if(box){box.classList.toggle('error',kind==='error');box.classList.toggle('success',kind==='success');box.textContent=message}};
document.addEventListener('click',event=>{const open=event.target.closest('[data-open-academic-dialog]');if(open){document.getElementById(open.dataset.openAcademicDialog)?.showModal();return}const close=event.target.closest('[data-close-academic-dialog]');if(close){close.closest('dialog')?.close();return}if(event.target.matches('dialog[data-academic-dialog]'))event.target.close()});
document.addEventListener('input',event=>{const input=event.target.closest('[data-academic-filter]');if(!input)return;const section=input.closest('[data-academic-list]');const query=input.value.trim().toLocaleLowerCase();let visible=0;section?.querySelectorAll('tbody tr').forEach(row=>{const match=row.textContent.toLocaleLowerCase().includes(query);row.hidden=!match;if(match)visible++});const status=section?.querySelector('[data-filter-status]');if(status)status.textContent=query?`${visible} matching records`:''});
document.addEventListener('submit',async event=>{const form=event.target.closest('form.academic-async');if(!form)return;event.preventDefault();const button=event.submitter||form.querySelector('[type=submit]');if(button?.disabled)return;const label=button?.textContent;if(button){button.disabled=true;button.textContent='Saving…'}try{const data=new FormData(form);data.set('_async','1');const response=await fetch(form.getAttribute('action')||location.href,{method:'POST',body:data,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'The record could not be saved.');const latest=await fetch(result.url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});if(!latest.ok)throw new Error('Saved, but updated academic data could not be loaded. Refresh the page.');const parsed=new DOMParser().parseFromString(await latest.text(),'text/html');const updated=parsed.querySelector('.academic-page');if(!updated)throw new Error('Saved, but the updated view could not be loaded. Refresh the page.');page()?.replaceWith(updated);history.replaceState({},'',result.url);setupClassAutocomplete(updated);announce('Academic record saved.')}catch(error){announce(error.message,'error');if(button){button.disabled=false;button.textContent=label||'Save'}}});
})();
</script>
</body></html>